INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(164000, 0, 0, '大人，塞文·达伦加尔领主已在暴风城要塞盘桓多日。去贵族议会找他吧。他身边尽是毒蛇。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Dharil Cohen'),
(164001, 0, 0, '我想我的立场已经说得很清楚了。巨魔、匪徒、艾尔迪尔……还要发生多少事，我们才肯下决心出手？', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Servin Darengar'),
(164001, 1, 0, '若我们袖手旁观，到头来便无物可治！我问你，难道溺水之人还得先开口哀求，我们才肯施救？', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Servin Darengar'),
(164001, 2, 0, '塞伦娅女士的傲慢会毁了我们所有人。我们必须——！', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Servin Darengar'),
(164001, 3, 0, '去斯卡德尔德我家族的庄园，把我的印信交给我儿子阿拉松。若我们要熬过这个时代的磨难，行省正需要你这样勇敢的人。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Servin Darengar'),
(164002, 0, 0, '把庄园上上下下搜个遍。哪怕掀开地板也在所不惜。塞伦娅女士对你寄予厚望。', 12, 0, 100, 0, 0, 0, 0, 0, 'captured in game'),
(164002, 1, 0, '你！对，就是你。过来。', 12, 0, 100, 0, 0, 0, 0, 0, 'captured in game'),
(164004, 0, 0, '为了斯卡德尔德！', 12, 0, 100, 0, 0, 0, 0, 0, 'Wild Ealdir'),
(164004, 0, 1, '我要用你的骨头打一把斧子。', 12, 0, 100, 0, 0, 0, 0, 0, 'Wild Ealdir'),
(164004, 0, 2, '你会成为乌鸦的口中食。', 12, 0, 100, 0, 0, 0, 0, 0, 'Wild Ealdir'),
(164004, 0, 3, '摩根娜会给你的灵魂派上用场。我们艾尔迪尔从不浪费任何东西。', 12, 0, 100, 0, 0, 0, 0, 0, 'Wild Ealdir'),
(164005, 0, 0, '什么事？是谁在那儿？我不是下过命令，不许打扰我吗？', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 1, 0, '你可以在王座厅找到德雷温爵士，他正主持战事。他知道该如何用你这样的才干。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 2, 0, '说说看……这毒本该起什么效？昏睡？麻痹？还是叫人躁动难安？又或许，只是一场干脆的心肌梗塞？我好奇得要命……至少，我本来是该没命的。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 3, 0, '我饶有兴致地一路追着你的足迹走过斯卡德尔德；我的眼线耳目遍布四方。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 4, 0, '我知道是谁派你来的。巴列斯卡达那个女巫拿我的脑袋当作结盟的价码，是吧？算上这次，他们已经三度下毒害我了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 5, 0, '然而，与摩根娜将要放出的黑暗相比，洛丹伦发生的一切都称得上美好回忆。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 6, 0, '所以，事情终于走到这一步。唉！圣光知道，我们需要黛尔德拉的援手才能阻止摩根娜。而我已经准备好付出它索要的代价：', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 7, 0, '我的性命。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164005, 8, 0, '安息吧，$C。今夜，全城都将哀悼它的摄政王。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Serenya Coldmere'),
(164006, 0, 0, '去西边的邓希尔找阿姆罗斯·达戈尔队长。以格雷斯基使节的身份自报家门。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Draewyn Unthar'),
(164006, 1, 0, '你可以在王者大道上的格雷斯基前哨找到温德海姆中士。他那个人……脾气有些特别。别把他的话放在心上。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Draewyn Unthar'),
(164006, 2, 0, '克雷斯特海恩虽有自己的治安官，镇民们寻求指点或慰藉时却都去找埃尔罗斯神父。他是个明断事理的人。无论他的忧虑从何而来，都请认真对待。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Draewyn Unthar'),
(164006, 3, 0, '这座城堡的大门将永远向你敞开，从今往后，永不改变。让所有人都知道，我册封你为格雷斯基骑士。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sir Draewyn Unthar'),
(164007, 0, 0, '路上当心点，好吗？我才刚认识你，倒也不是多关心你，可这批货值钱得很。何况斯卡德尔德危险得很……留神脚下！', 12, 0, 100, 0, 0, 0, 0, 0, 'Hilma Golar'),
(164010, 0, 0, '顺着上山的小路走，就能找到矿洞。对付豺狼人，谨慎是你最好的武器；它们成群扑上来时，可是致命的。', 12, 0, 100, 0, 0, 0, 0, 0, 'Captain Amros Dhagor'),
(164010, 1, 0, '你……确定吗？豺狼人很少跑到这么北的地方来，不过南方诸省倒是习惯了应付它们。至于那样的诅咒，我可从未听说过。', 12, 0, 100, 0, 0, 0, 0, 0, 'Captain Amros Dhagor'),
(164010, 2, 0, '女巫？你有多少胆量，就缺多少脑子：斯卡德尔德人人都知道女巫信不得。说不定那诅咒根本就是她自己下的！', 12, 0, 100, 0, 0, 0, 0, 0, 'Captain Amros Dhagor'),
(164011, 0, 0, '我们身处战时；对敌人施以仁慈便是叛国。拔出你的剑，收起你的道义。把他们全部了结。杀光巨魔。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sergeant Windhelm'),
(164012, 0, 0, '这可真是一团血污。消息迟早会传出去的。到那时……愿圣光保佑我们！', 12, 0, 100, 0, 0, 0, 0, 0, 'Mountaineer Thandel - 175107 rewarded'),
(164012, 1, 0, '沿着那条小径去矿洞，把那里彻底搜一遍。那些矿坑里一定还有活人。我不信艾尔迪尔能把他们一个不剩地全抓走。', 12, 0, 100, 0, 0, 0, 0, 0, 'Mountaineer Thandel - 175108 accepted'),
(164012, 2, 0, '好了。我已经把劳瑞林和泰尔佩里昂的营地标在你的地图上了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Mountaineer Thandel - 175111 accepted'),
(164013, 0, 0, '哦，欢迎。恐怕今日没有布道了。说实话，有一阵子我都不会主持弥撒了。', 12, 0, 100, 0, 0, 0, 0, 1, 'Father Elroth - Greets players'),
(164013, 1, 0, '通往墓穴的阶梯就在那边，我的左手边。下去要小心。你会遇到亡灵……但或许还有更糟的东西。', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Elroth - On Noises Below accepted'),
(164014, 0, 0, '悬空圣风修道院是整个斯卡德尔德最神圣的所在，也是王国最重要的朝圣之地之一。不必多说，你去见阿姆罗德神父时，务必以应有的礼数待他。', 12, 0, 100, 0, 0, 0, 0, 0, 'Chaplain Conther'),
(164017, 0, 0, '此去路上，务必谨慎。', 12, 0, 100, 0, 0, 0, 0, 0, 'Guard Dornhelm - A Sword for the North rewarded'),
(164020, 0, 0, '你那些袋子里有烟叶吗？', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Bandit'),
(164020, 0, 1, '那商人已经付过账了……现在轮到你了！', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Bandit'),
(164020, 0, 2, '国王的目光从不望向北方。', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Bandit'),
(164020, 0, 3, '跟我们比起来，迪菲亚不过是个笑话。', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Bandit'),
(164021, 0, 0, '又一个偏离大道的英雄。', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Marauder'),
(164021, 0, 1, '你在这儿干什么！？', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Marauder'),
(164021, 0, 2, '既不属于艾尔迪尔，也不属于王国。自由自在！', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Marauder'),
(164021, 0, 3, '在这儿，哪个国王都不算数！', 14, 0, 100, 0, 0, 0, 0, 0, 'Road Marauder'),
(164022, 0, 0, '只要湖里还有鱼人，我抛多少次竿都无所谓……', 12, 0, 100, 0, 0, 0, 0, 0, 'Edrin Salmear'),
(164026, 0, 0, '啊，还有，先别打开那只瓶子！', 12, 0, 100, 0, 0, 0, 0, 0, 'Little Mickey'),
(164032, 0, 0, '那个人；唔，他的残骸：阿尔托·比尔伯格。我认识他，你知道吗？多年前他女儿病倒时，他跑到这里来，指控我给她下了咒。他还威胁要把我这窝棚烧成灰。', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164032, 1, 0, '所以我再问一遍：我凭什么帮他们？因为那是「正确」的事？我早就学会不按对错行事，只按利害行事。', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164032, 2, 0, '去花丛里找那些小精灵。用力摇一摇，它们立马就会冒出来，把你烦得要死。你就知道它们有多「有趣」了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164032, 3, 0, '三姐妹，是吧？见过她们的人寥寥无几；对许多人来说，她们不过是传说。别怕；我会赐你祝福。要是你没落得个死，希望你在她们面前为我美言几句。', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164032, 4, 0, '我想有个人或许能帮上忙。要见到她可不容易，但你已证明自己愿意为这些人豁出性命。仔细听好：', 12, 0, 100, 0, 0, 0, 0, 0, 'Beldred'),
(164033, 0, 0, '跟三姐妹玩得开心点！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164033, 0, 1, '蠢货！我的手艺可是卡斯巴德亲传的！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164033, 0, 2, '你的血将滋养这片土地。', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164033, 0, 3, '那么，你选择了死亡。', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164033, 0, 4, '神灵们，我把这场死亡献予你们！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164034, 0, 0, '真正的甜食爱好者都想尝一尝那大名鼎鼎的邓希尔蛋糕！', 12, 0, 100, 0, 0, 0, 0, 0, 'Hestwin Honeycrust'),
(164034, 1, 0, '去找旅店老板米拉尔达多要些牛奶！我们做蛋糕要用！', 12, 0, 100, 0, 0, 0, 0, 0, 'Hestwin Honeycrust'),
(164034, 2, 0, '我只需要一点时间烤馅饼。耐心，耐心！', 12, 0, 100, 0, 0, 0, 0, 0, 'Hestwin Honeycrust'),
(164034, 3, 0, '大功告成！邓希尔馅饼做好了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Hestwin Honeycrust'),
(164035, 0, 0, '用尽全力转动曲柄！别停下！', 12, 0, 100, 0, 0, 0, 0, 0, 'Miller Bartren'),
(164035, 1, 0, '就是这样！面粉磨得再好不过了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Miller Bartren'),
(164035, 2, 0, '妙极了！就算来一阵狂风也比不上你。', 12, 0, 100, 0, 0, 0, 0, 0, 'Miller Bartren'),
(164035, 3, 0, '你让那磨坊转得像十二头牛在拉！现在，好好享用馅饼吧！', 12, 0, 100, 0, 0, 0, 0, 0, 'Miller Bartren'),
(164037, 0, 0, '记住：去圣所找哈尔丁·绿歌。告诉他，你是代表我来的。', 12, 0, 100, 0, 0, 0, 0, 0, 'Darond'),
(164043, 0, 0, '摩根娜会给你的灵魂派上用场。我们艾尔迪尔从不浪费任何东西。', 12, 0, 100, 0, 0, 0, 0, 0, 'Jagged Cave Ealdir'),
(164043, 0, 1, '我要用你的骨头打一把斧子。', 12, 0, 100, 0, 0, 0, 0, 0, 'Jagged Cave Ealdir'),
(164045, 0, 0, '诅咒你们！诅咒你们每一个人！', 12, 0, 100, 0, 0, 0, 0, 1, 'Cairn'),
(164045, 1, 0, '我杀了他。是的。我杀了我的兄弟。那个叛徒……死了倒便宜他了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Cairn'),
(164045, 2, 0, '你先走吧。我想，我还要过一阵子才回克雷斯特海恩。我就等风波平息下来。', 12, 0, 100, 0, 0, 0, 0, 0, 'Cairn'),
(164047, 0, 0, '站住。', 14, 0, 100, 0, 0, 0, 0, 0, 'Raigh Anramor - disguised player approaches'),
(164048, 0, 0, '瞧瞧，这是什么东西？你真以为自己能从我这抢走艾尔德梅因酋长之位？哈！', 14, 0, 100, 0, 0, 0, 0, 0, 'Cragarn - aggro'),
(164048, 1, 0, '你会成为给其他人的一个教训。', 14, 0, 100, 0, 0, 0, 0, 0, 'Cragarn - first combat line'),
(164048, 2, 0, '我要活剥了你的皮。女巫会用你的皮给我缝一条腰布！', 14, 0, 100, 0, 0, 0, 0, 0, 'Cragarn - second combat line'),
(164048, 3, 0, '噢，神灵啊……怜悯……我的……灵魂……', 14, 0, 100, 0, 0, 0, 0, 0, 'Cragarn - death'),
(164049, 0, 0, '退后！你疯了吗？', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - disguised player too close'),
(164049, 1, 0, '退后！你疯了吗？', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - aggro'),
(164049, 1, 1, '你以为你在干什么？', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - aggro'),
(164049, 1, 2, '这会让你付出惨重代价。', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - aggro'),
(164049, 1, 3, '想要训练，就去找个见习者！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Ealdir - aggro'),
(164050, 0, 0, '嘘！对，就是你！过来！', 12, 0, 100, 0, 0, 0, 0, 0, 'Randec'),
(164050, 1, 0, '让我看看你。好，很好。这样能蒙混过去。只是务必板着一张臭脸。那些艾尔迪尔整天都挂着那副表情。', 12, 0, 100, 0, 0, 0, 0, 0, 'Randec'),
(164055, 0, 0, '谢谢你……呃啊！', 12, 0, 100, 0, 0, 0, 0, 0, 'Wounded Graysky Soldier'),
(164056, 0, 0, '谢谢你……呃啊！', 12, 0, 100, 0, 0, 0, 0, 0, 'Wounded Graysky Soldier'),
(164060, 0, 0, '还有，看在老天的份上，进去后留神脚下！我最不需要的，就是在自己的差事之外还得去救你这条命。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lieutenant Frieren'),
(164060, 1, 0, '巨魔在祖拉蒙达挨的那一击，要很久才能缓过来。他们再也不敢小看我们了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lieutenant Frieren'),
(164060, 2, 0, '你救出的人质已躲进那座旧瞭望塔。去看看他们，确认他们安然无恙。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lieutenant Frieren'),
(164061, 0, 0, '公主有了强大的盟友……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 1, '为了梅克西特拉！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 2, '你的孩子将来都要当孤儿……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 3, '为了霜鬃！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 4, '我打赌你味道不错……让我咬一口！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 5, '我得到了洛阿的祝福！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 6, '我不会给你亲人留下能哭的尸首……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 7, '为了远古帝国！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 8, '德鲁克塔尔永存！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 9, '死吧！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 10, '我们要把你们全杀光。就从你开始！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 11, '你的死让我们离荣耀之日更近一步！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 12, '你凭什么觉得自己能打赢我？', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 13, '绝不留情！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 14, '我杀过几十个你这样的家伙……你怎么就不肯认输？', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 15, '为梅克西特拉赢得胜利！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 16, '我要把你吃得干干净净！连骨头都不剩！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 17, '我可不怕你！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 18, '这些土地是我们的！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 0, 19, '你要为你们祖先偷走的东西付出代价！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
(164061, 1, 0, '又少了一桩烦心事。', 14, 0, 100, 0, 0, 0, 0, 0, 'Frostmane Ambusher'),
