(164062, 0, 19, '你要为你们祖先偷走的东西付出代价！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Reaper'),
(164062, 1, 0, '又少了一桩烦心事。', 14, 0, 100, 0, 0, 0, 0, 0, 'Frostmane Reaper'),
(164063, 0, 0, '俺们公主可找着了厉害的盟友……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 1, '为了梅克西特拉！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 2, '你们这帮崽子都得成孤儿……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 3, '为了霜鬃！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 4, '俺打赌你尝起来不错……让俺咬一口！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 5, '俺有洛阿的祝福！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 6, '俺不会给你亲人留下能哭的尸首……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 7, '为了古老帝国！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 8, '德鲁克塔尔永存！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 9, '死吧！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 10, '俺们要把你们全杀光，就从你开始！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 11, '你的死让俺们离荣耀之日更近一步！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 12, '你凭什么觉得自己打得过俺？', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 13, '绝不留情！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 14, '俺杀过几十个你这样的……你咋还不认输？', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 15, '胜利属于梅克西特拉！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 16, '俺要把它全吃光！骨头也不剩！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 17, '俺才不怕你！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 18, '这些土地是俺们的！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 0, 19, '你们祖先从俺们这儿偷走的东西，你们得还！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164063, 1, 0, '又少了一桩心事。', 14, 0, 100, 0, 0, 0, 0, 0, 'Frostmane Stalker'),
(164064, 0, 0, '你不是他们的人。你不是他们的人！', 14, 0, 50, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164064, 0, 1, '他们杀了那么多人……吃了那么多人……！', 14, 0, 50, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164064, 1, 0, '赞美圣光！', 14, 0, 33.3, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164064, 1, 1, '你……你把他们都杀了吗？可以出去了吗？', 14, 0, 33.3, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164064, 1, 2, '你把我从比死更可怕的境地救了出来……', 14, 0, 33.3, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164064, 2, 0, '我以为……我会烂在里面……谢谢你。', 14, 0, 25, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164064, 2, 1, '从这里开始……我能自己走……我想可以……啊！谢谢你……', 14, 0, 25, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164064, 2, 2, '还有很多人和我一样。几十个俘虏……', 14, 0, 25, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164064, 2, 3, '别停手，把那些野人杀到一个不剩……', 14, 0, 25, 0, 0, 0, 0, 0, 'Captive Hostage'),
(164066, 0, 0, '你走得太远了。很抱歉，我必须杀了你。荣誉地战斗吧，我向你保证，绝不会让他们分食你的尸身。', 14, 0, 100, 0, 0, 0, 0, 0, 'Emissary Agramor'),
(164066, 1, 0, '你打得不错！你的首领有你这样的人，是他们的运气。', 14, 0, 100, 0, 0, 0, 0, 0, 'Emissary Agramor'),
(164066, 2, 0, '哈！这一仗打完，我得去找个巫医了。', 14, 0, 100, 0, 0, 0, 0, 0, 'Emissary Agramor'),
(164066, 3, 0, '一场……光荣的死。可是……', 14, 0, 100, 0, 0, 0, 0, 0, 'Emissary Agramor'),
(164067, 0, 0, '我恳求你带路吧。因为被圣光拥抱的人，便不再是孤儿。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sister Sarah'),
(164071, 0, 0, '俺杀过太多你这样的了……你已经让俺觉得无聊了！', 14, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - aggro'),
(164071, 1, 0, '俺杀了多少？早就数不清了……', 14, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - combat'),
(164071, 1, 1, '俺可是王族出身。你们不过是一群渣滓。', 14, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - combat'),
(164071, 1, 2, '就你们这种瘦巴巴的东西，打得还算不错！', 14, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - combat'),
(164071, 1, 3, '泽莱扎克，你玩得开心吗？', 14, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - combat'),
(164071, 1, 4, '俺都吃饱了，不过你非要的话……泽莱扎克永远饿！', 14, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - combat'),
(164071, 2, 0, '梅克西特拉，俺的公主……俺辜负了你……', 12, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - death'),
(164071, 2, 1, '到头来你瞧……桥会被这么多尸首压塌的……', 14, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - death'),
(164071, 3, 0, '趁还能走就回去吧！矮人才是俺们真正的敌人。你们这么想要斯卡德尔德，那就拿去……', 14, 0, 100, 0, 0, 0, 0, 0, 'Alta\'zin - approach warning'),
(164074, 0, 0, '众灵庇佑我们的事业！', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 1, '为了众灵！', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 2, '血流成河。', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 3, '城里的渣滓。', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 4, '让斯卡德尔德自由！', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 5, '女巫会带走你的孩子！', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 6, '王国必亡！', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 7, '你们都是闯入我们土地的侵略者。', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 8, '胜利属于艾尔迪尔！', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164074, 0, 9, '斯卡德尔德必将自由！', 14, 0, 100, 0, 0, 0, 0, 0, 'Scaidern Ealdir'),
(164075, 0, 0, '哈！格雷斯基那个荡妇是送你来送死的。', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Rallagh'),
(164075, 1, 0, '我要把你的骨头扔给狗啃！', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Rallagh'),
(164075, 1, 1, '我要把你的头颅挂上尖桩！', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Rallagh'),
(164075, 1, 2, '这一切……只为了一滴血？', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Rallagh'),
(164075, 2, 0, '当你坚信一个信念……你就永远不会真正死去……', 12, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Rallagh'),
(164076, 0, 0, '众灵庇佑我们的事业！', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 1, '为了众灵！', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 2, '血流成河。', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 3, '城里的渣滓。', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 4, '让斯卡德尔德自由！', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 5, '女巫会带走你的孩子！', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 6, '王国必亡！', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 7, '你们都是闯入我们土地的侵略者。', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 8, '胜利属于艾尔迪尔！', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164076, 0, 9, '斯卡德尔德必将自由！', 14, 0, 100, 0, 0, 0, 0, 0, 'Galdaern Ealdir'),
(164077, 0, 0, '有种就来抓我！', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad'),
(164077, 1, 0, '我要在你心还在跳的时候把它从你胸膛里掏出来。你最后看到的，将是我沾满鲜血的血盆大口。', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(164077, 1, 1, '雇佣兵渣滓！', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad'),
(164077, 1, 2, '你就这点本事？', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad'),
(164077, 2, 0, '你不过是……一个低贱的雇佣剑客……', 12, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Thornad'),
(164079, 0, 0, '我总说，造它们的神准是把零件装反了：上半身本该是狮子而不是鹰，因为它们吃起来跟狮子一模一样！', 12, 0, 100, 0, 0, 0, 0, 0, 'Gryphon Keeper Bromli - Gryphon Appetizer rewarded'),
(164079, 1, 0, '作为这一行的专家，你听我的准没错：用不了多久，这些狮鹫就会喜欢上你。事实上……', 12, 0, 100, 0, 0, 0, 0, 0, 'Gryphon Keeper Bromli - Nests and Feathers rewarded'),
(164081, 0, 0, '跟三姐妹好好玩玩吧！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164081, 0, 1, '蠢货！我的手艺是卡斯巴德亲自教的！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164081, 0, 2, '你的血将滋养这片土地。', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164081, 0, 3, '那么，你选择了死亡。', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164081, 0, 4, '众灵啊，我把这场死亡献给你们！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ealdir Dark Druid'),
(164161, 0, 0, '附近回荡起一声野蛮的嚎叫。%s 出现了', 41, 0, 100, 0, 0, 0, 0, 2, 'Skymaw - On Respawn - zone announcement'),
(164172, 0, 0, '赫斯特温说，面团得“自己呼出那股魔力”……', 12, 0, 100, 0, 0, 0, 0, 0, 'Geralda'),
(164172, 1, 0, '我看他就是喜欢趁你饿着的时候让你干等。', 12, 0, 100, 0, 0, 0, 0, 0, 'Geralda'),
(164172, 2, 0, '不过说实话，这等待是值得的。', 12, 0, 100, 0, 0, 0, 0, 0, 'Geralda'),
(164196, 0, 0, '你要明白：没有真理就没有善，没有启示就没有真理。人是会犯错的，他的感官不过是幻象。', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - sermon 1'),
(164196, 1, 0, '无论你的心多么高尚，只要你的剑听命于谎言，你侍奉的就不是圣光，而是暗影。在真理之外，一切美德都只是伪装起来的罪恶。', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - sermon 2'),
(164196, 2, 0, '别害怕，$gson:daughter;：软弱同样是一种罪。惩戒罪人并无羞耻可言。圣光不需要懦夫做它的使者。', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - 175013 accepted'),
(164196, 3, 0, '愿圣光指引你的脚步，我的$gson:daughter;。也愿那些可憎之物学会畏惧你正义的怒火。', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - 175014 accepted'),
(164196, 4, 0, '啊，$ghe:she;来了！圣光的工具，正义的武器。你已经把他们清除干净了，不是吗？否则你不会回来。', 12, 0, 100, 0, 0, 0, 0, 0, 'Father Amrod - player returns from Grimepit'),
(164197, 0, 0, '我辜负了圣光对我的期望。', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - pre-duel'),
(164197, 0, 1, '我怕我已倾尽所有……却仍然不够。', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - pre-duel'),
(164197, 1, 0, '我不会让我的信仰动摇。', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 1, 1, '今天，我会想起自己为何立誓效命。', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 1, 2, '我不能辜负我的誓言！', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 1, 3, '让我的剑替我践行誓言！', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 1, 4, '你会看到我的虔诚是否足够！', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164197, 2, 0, '我会弥补这次失败。我向你保证。', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - defeated'),
(164197, 2, 1, '愿圣光宽恕我。', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - defeated'),
(164198, 0, 0, '我辜负了圣光对我的期望。', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - pre-duel'),
