(164204, 1, 1, '今天，我会想起自己为何立誓效命。', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164204, 1, 2, '我不能辜负我的誓言！', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164204, 1, 3, '让我的剑替我践行誓言！', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164204, 1, 4, '你会看到我的虔诚是否足够！', 14, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - duel start'),
(164204, 2, 0, '我会弥补这次失败。我向你保证。', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - defeated'),
(164204, 2, 1, '愿圣光宽恕我。', 12, 0, 100, 0, 0, 0, 0, 0, 'Hallow Wind Initiate - defeated'),
(164205, 0, 0, '退后，怪物！我还有力气……！啊，哦。呃！你……你不是穴居怪。', 12, 0, 100, 0, 0, 0, 0, 0, 'Crusader Diallos - player arrives on 175014'),
(164205, 1, 0, '杀了他们……把他们全杀了……那些可憎的野兽。那副扭曲的活物模样。为死去的同伴报仇！', 12, 0, 100, 0, 0, 0, 0, 0, 'Crusader Diallos - 175015 accepted'),
(164206, 0, 0, '依国王的律法，你的判决是死刑。', 14, 0, 100, 0, 0, 0, 0, 0, 'Grimepit Trogg - aggro'),
(164206, 0, 1, '尝尝污坑的待客之道吧！', 14, 0, 100, 0, 0, 0, 0, 0, 'Grimepit Trogg - aggro'),
(164206, 0, 2, '我们杀死的那些十字军正在暗影界等着你。', 14, 0, 100, 0, 0, 0, 0, 0, 'Grimepit Trogg - aggro'),
(164206, 0, 3, '入侵者！吹响警报！', 14, 0, 100, 0, 0, 0, 0, 0, 'Grimepit Trogg - aggro'),
(164206, 1, 0, '可是……我的家人……', 12, 0, 100, 0, 0, 0, 0, 0, 'Grimepit Trogg - death'),
(164206, 1, 1, '别杀……孩子……', 12, 0, 100, 0, 0, 0, 0, 0, 'Grimepit Trogg - death'),
(164206, 1, 2, '你……才是……入侵者……', 12, 0, 100, 0, 0, 0, 0, 0, 'Grimepit Trogg - death'),
(164206, 1, 3, '我也……曾有……梦想……', 12, 0, 100, 0, 0, 0, 0, 0, 'Grimepit Trogg - death'),
(164210, 0, 0, '你们就是一帮暴徒，知道吗？更糟的是：还是贼！', 12, 0, 100, 0, 0, 0, 0, 0, 'captured in game'),
(164210, 1, 0, '尽管记载含糊，日记里还是提到了那口井，以及庄园底下的一处洞窟。也许值得去看看。', 12, 0, 100, 0, 0, 0, 0, 0, 'captured in game'),
(164211, 0, 0, '而我认为，我们的立场已经表达得很清楚了，达伦加尔领主。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Aldous Bruck'),
(164211, 1, 0, '即使意见一致，没有冷沼家族的同意，本议会也不能就这样把军队开进斯卡德尔德。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Aldous Bruck'),
(164211, 2, 0, '你是在浪费时间，还找错了地方，达伦加尔领主。我们的律法存在自有其道理。本次会议到此结束。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lord Aldous Bruck'),
(164212, 0, 0, '也请记住，统治斯卡德尔德的是冷沼家族，而不是你自己。', 12, 0, 100, 0, 0, 0, 0, 0, 'Countess Cecilia Clessington'),
(164221, 0, 0, '等等！我是朋友！朋友！把武器收起来，好吗？', 12, 0, 100, 0, 0, 0, 0, 0, 'Alto Bilberg - Player in sight'),
(164226, 0, 0, '哈！你打架像个杂货铺老板！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164226, 0, 1, '我倒是要看看你能不能活着打完这一仗！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164227, 0, 0, '哈！你打架像个杂货铺老板！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164227, 0, 1, '我倒是要看看你能不能活着打完这一仗！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164228, 0, 0, '哈！你打架像个杂货铺老板！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
