(164231, 0, 1, '我倒是要看看你能不能活着打完这一仗！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164232, 0, 0, '哈！你打架像个杂货铺老板！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164232, 0, 1, '我倒是要看看你能不能活着打完这一仗！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164233, 0, 0, '哈！你打架像个杂货铺老板！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164233, 0, 1, '我倒是要看看你能不能活着打完这一仗！', 14, 0, 100, 0, 0, 0, 0, 0, 'Ealdmaine Aspirant'),
(164235, 0, 0, '拉尔达住在湖边的那栋房子里。请把食物送去给她。', 12, 0, 100, 0, 0, 0, 0, 0, 'Fernad'),
(164236, 0, 0, '多萝西……？哦……', 12, 0, 100, 0, 0, 0, 0, 0, 'Ralda'),
(164236, 1, 0, '鱼人抓走了我的小多萝西！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ralda'),
(164236, 2, 0, '只要有一点我女儿下落的线索，对我来说就够了……', 12, 0, 100, 0, 0, 0, 0, 0, 'Ralda'),
(164236, 3, 0, '是狗头人抓走了多萝西！就是他们！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ralda'),
(164236, 4, 0, '你找到我女儿了吗？！有什么线索吗？', 12, 0, 100, 0, 0, 0, 0, 0, 'Ralda'),
(164238, 0, 0, '拉尔达……哦，拉尔达！', 12, 0, 100, 0, 0, 0, 0, 0, 'Rothfuss - Dorothy talk 1/5'),
(164238, 1, 0, '她让你东奔西跑，是不是？鱼人、狗头人……自从……多萝西之后，她就再也不是原来的样子了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Rothfuss - Dorothy talk 2/5'),
(164238, 2, 0, '多萝西没有失踪，也没人掳走她。她几个月前就死了……是溺亡。那是一场意外，一时的疏忽，可拉尔达……她承受不了那份愧疚。愧疚把她击垮了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Rothfuss - Dorothy talk 3/5'),
(164238, 3, 0, '有时候她说服自己多萝西还活着；有时候她又蜷成一团，睡在她的坟旁，任凭风吹雨打。只要职责允许，我就会回到她身边。', 12, 0, 100, 0, 0, 0, 0, 0, 'Rothfuss - Dorothy talk 4/5'),
(164238, 4, 0, '抱歉……很抱歉她把你牵扯进来。', 12, 0, 100, 0, 0, 0, 0, 0, 'Rothfuss - Dorothy talk 5/5'),
(164238, 5, 0, '下楼梯到地下室去，在地板上找一扇活板门。它有时会卡住，别怕，用力狠狠地一拽。', 12, 0, 100, 0, 0, 0, 0, 0, 'Rothfuss - On Arathel\'s Camp accepted'),
(164243, 0, 0, '兽人正背对着我们。他们的后背又宽又厚……简直在求人捅上一刀。抓住这个机会。', 12, 0, 100, 0, 0, 0, 0, 0, 'Arathel - on quest accept'),
(164247, 0, 0, '为了凯雷博尔！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164247, 0, 1, '我要把你的头骨做成战利品。', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164247, 0, 2, '奥克玛卡！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164247, 0, 3, '蓝色的渣滓！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164247, 0, 4, '鼠辈！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164247, 0, 5, '你这种人根本不是我的对手！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164247, 0, 6, '让我见识你的血！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164247, 0, 7, '我们会杀光你们，连你们的孩子也不放过……', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164247, 0, 8, '受死吧！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Besieger - aggro'),
(164248, 0, 0, '你听过那句谚语吗？“别向精灵求建议，他们既会说不，也会说是。”和他们打交道时可要当心！', 12, 0, 100, 0, 0, 0, 0, 0, 'Ketheric Sadson - on quest accept'),
(164252, 0, 0, '装满双耳瓶后，就回要塞去。这附魔之水能治愈最肮脏的伤口，也能驱除最凶险的疾病；取用它时要有分寸。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sanadriel - on quest accept'),
(164253, 0, 0, '受死吧！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164253, 0, 1, '奥克玛卡！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164253, 0, 2, '为了凯雷博尔！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164253, 0, 3, '但愿你比上一个撑得久些。别吓尿了！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164253, 0, 4, '我要把你的头骨做成战利品。', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164253, 0, 5, '我们会杀光你们，连你们的孩子也不放过……', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164253, 0, 6, '你这种人根本不是我的对手！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164253, 0, 7, '洛克塔尔！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164253, 0, 8, '鼠辈！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Orc - aggro'),
(164254, 0, 0, '等等，等等！是你先上，还是我先来？', 12, 0, 100, 0, 0, 0, 0, 0, 'Andraste Recruit - duel start'),
(164254, 1, 0, '这剑也许挺花哨，可我用惯了草耙。相信我，拿草耙打起来比这玩意儿强多了！', 12, 0, 100, 0, 0, 0, 0, 0, 'Andraste Recruit - during the duel'),
(164254, 1, 1, '既然这里已经有你了，他们干嘛还从那么远的地方征召我们？', 12, 0, 100, 0, 0, 0, 0, 0, 'Andraste Recruit - during the duel'),
(164254, 2, 0, '受了这样的羞辱，也许我对大业还有些用处……当炮灰也算。', 12, 0, 100, 0, 0, 0, 0, 0, 'Andraste Recruit - yields'),
(164254, 2, 1, '我想……我想那股好战的劲儿已经离我而去了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Andraste Recruit - yields'),
