(164261, 1, 1, '既然这里已经有你了，他们干嘛还从那么远的地方征召我们？', 12, 0, 100, 0, 0, 0, 0, 0, 'Andraste Recruit - during the duel'),
(164261, 2, 0, '受了这样的羞辱，也许我对大业还有些用处……当炮灰也算。', 12, 0, 100, 0, 0, 0, 0, 0, 'Andraste Recruit - yields'),
(164261, 2, 1, '我想……我想那股好战的劲儿已经离我而去了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Andraste Recruit - yields'),
(164262, 0, 0, '老兵给你一句忠告：爬上那座废弃的攻城塔，就能溜进凯雷博尔。当然，前提是你想悄悄行事。', 12, 0, 100, 0, 0, 0, 0, 0, 'Arendor - accepts The Three of Kerebor'),
(164265, 0, 0, '背信弃义的腐肉！我要杀了你，我要把你剁成碎块。然后……', 14, 0, 100, 0, 0, 0, 0, 0, 'Butcher Eigor - aggro'),
(164265, 1, 0, '接下来我要对你的残骸做的事，会让你祖先的灵魂都作呕！', 14, 0, 100, 0, 0, 0, 0, 0, 'Butcher Eigor - follows the aggro yell');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(164266, 0, 0, '啊，正当祭品快要不够用的时候……跟我来！', 14, 0, 100, 0, 0, 0, 0, 0, 'Karegor Grimfang - aggro'),
(164266, 1, 0, '我要的东西不多，只是……你的灵魂。', 14, 0, 100, 0, 0, 0, 0, 0, 'Karegor Grimfang - follows the aggro yell'),
(164267, 0, 0, '鲜血。细嫩的皮肉。还有吓得尿湿的裤子。正合我的胃口。', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Champion Kurgan - aggro'),
(164267, 0, 1, '为了走到我面前，你有几个人倒下了？很好。省得我亲自动手清理那些废物。', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Champion Kurgan - aggro'),
(164267, 0, 2, '等我收拾完你……我要对你做的事……连死灵法术都没法把你带回来。', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Champion Kurgan - aggro'),
(164267, 1, 0, '我要把你的尸体像雨点一样砸在安德拉斯特要塞上。', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Champion Kurgan - combat'),
(164267, 1, 1, '你竟让我流血了？哈！', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Champion Kurgan - combat'),
(164267, 1, 2, '派你来的那些人，那些军情七处的鼠辈……你的尸体就是给他们的警告。', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Champion Kurgan - combat'),
(164267, 2, 0, '真是吵闹的……死法……正合她的心意……哈……', 12, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Champion Kurgan - death'),
(164267, 3, 0, '凯雷博尔堡将是你的坟墓。', 14, 0, 100, 0, 0, 0, 0, 0, 'Blackrock Champion Kurgan - follows the aggro yell'),
(164269, 0, 0, '北郡近在咫尺……', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Spy - aggro'),
(164269, 0, 1, '你的喉咙被人割开过吗？凡事总有第一次……', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Spy - aggro'),
(164269, 0, 2, '我要看着你的血溅出来。', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Spy - aggro'),
(164269, 0, 3, '她……她会想让我把你的头带给她。', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Spy - aggro'),
(164269, 0, 4, '蠢货……我们不过是后卫部队。', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Spy - aggro'),
(164270, 0, 0, '受死吧！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164270, 0, 1, '让我见识你的血！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164270, 0, 2, '我们会杀光你们，连你们的孩子也不放过……', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164270, 0, 3, '蓝色的渣滓！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164270, 0, 4, '洛克塔尔！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164270, 0, 5, '你这种人根本不是我的对手！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164270, 0, 6, '鼠辈！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164270, 0, 7, '奥克玛卡！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164270, 0, 8, '但愿你比上一个撑得久些。别吓尿了！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Infiltrator - aggro'),
(164271, 0, 0, '蓝色的渣滓！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Guard - aggro'),
(164271, 0, 1, '但愿你比上一个撑得久些。别吓尿了！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Guard - aggro'),
(164271, 0, 2, '我要把你的头骨做成战利品。', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Guard - aggro'),
(164271, 0, 3, '让我见识你的血！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Guard - aggro'),
(164271, 0, 4, '为了凯雷博尔！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Guard - aggro'),
(164271, 0, 5, '受死吧！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kerebor Guard - aggro'),
(164274, 0, 0, '你的灵魂会成为我们的引火之物。', 14, 0, 100, 0, 0, 0, 0, 0, 'Shadowburn Prospector - aggro'),
(164274, 0, 1, '我没打算挖个坑把你埋了。你只会成为秃鹫的食料。', 14, 0, 100, 0, 0, 0, 0, 0, 'Shadowburn Prospector - aggro'),
(164274, 0, 2, '真是倒霉的相遇。公会对多管闲事者的规矩是……死。', 14, 0, 100, 0, 0, 0, 0, 0, 'Shadowburn Prospector - aggro'),
(164274, 0, 3, '你要明白……我们奉行严格的不留活口原则。', 14, 0, 100, 0, 0, 0, 0, 0, 'Shadowburn Prospector - aggro'),
(164278, 0, 0, '树人会很敌对；用你的暴力回应它们的暴力，不必畏惧。水晶里的法术只有在你先削弱它们之后才会生效。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Amaranthe Naemyl - On Anger Not Easily Appeased accepted'),
(164278, 1, 0, '厄尔达娅之厅的防护附魔，我亲自帮考拉诺斯编缀过。我们都清楚它们蕴含的危险，也清楚它们可能招来何种黑暗的注视。如果血精灵不惜代价强行闯入其中……', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Amaranthe Naemyl - On The Chambers of Erdaya accepted (1/2)'),
(164278, 2, 0, '他们的野心昭然若揭：从牢笼中放出那个囚徒。雪人称之为黑雪，艾尔迪尔称之为盘根之影。名号而已。我不会说出它真正的名字，免得白昼之光也被染暗。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Amaranthe Naemyl - On The Chambers of Erdaya accepted (2/2)'),
(164278, 3, 0, '带着圣所的祝福离去吧，也带上此地所有精灵的感激。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Amaranthe Naemyl - On Blessed Seed of a New Beginning accepted'),
(164278, 4, 0, '我知道你看见了什么。因为它同样在我脑中。你拯救了这座山谷，$n。不止是山谷。尽管付出的代价实在太过沉重。', 12, 0, 100, 0, 0, 0, 0, 0, 'Lady Amaranthe Naemyl - Player with The Cult Patriarch complete in sight'),
(164302, 0, 0, '若那些水晶的邪恶魔法仍在抽干山谷的生机，光杀了魔导师并不足以让森林平静下来。务必把它们摧毁。', 12, 0, 100, 0, 0, 0, 0, 0, 'Cauranos - 175097 accepted'),
(164302, 1, 0, '血精灵，以及他们对魔法毫不负责任的渴求，正危及森林的平衡。', 12, 0, 100, 0, 0, 0, 0, 0, 'Cauranos - 175098 accepted'),
(164302, 2, 0, '万古之前，泰坦在这些土地之下挖出了一座牢狱。就像筛子用来筛麦子，这片森林的树木也在筛滤从中逸出的能量。圣所的精灵们知道这一点。血精灵可能也知道；若真如此，那些魔导师不过是掩护。你必须立刻警告阿玛兰瑟女士。', 12, 0, 100, 0, 0, 0, 0, 0, 'Cauranos - 175099 accepted'),
(164302, 3, 0, '平静些，朋友们！这里并非人人都是我们的敌人。靠近些，不必害怕。你的心是高尚的。你是来帮助我们吗？', 12, 0, 100, 0, 0, 0, 0, 0, 'Cauranos - greeting'),
(164305, 0, 0, '这里。我受伤了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Meredyl Sunheart - approach'),
(164305, 1, 0, '被诅咒的小精灵……小心它们，好吗？一定是有什么把它们逼疯了。这山谷正经历着古怪的日子……', 12, 0, 100, 0, 0, 0, 0, 0, 'Meredyl Sunheart - 175095 accepted'),
(164309, 0, 0, '杀了他们。全都杀了。了结他们。从这里到他们的首领，铺一条尸体铺成的地毯。把他也杀了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Enilith Naemyl - On A Cult Within the Embassy accepted'),
(164309, 1, 0, '该死的……！等黑暗女士听说这桩背叛……艾泽拉斯再也没有哪个角落能让你躲过她的怒火。', 12, 0, 100, 0, 0, 0, 0, 0, 'Enilith Naemyl - Player on The Chambers of Erdaya in sight'),
(164310, 0, 0, '愿暗影吞噬你！', 14, 0, 25, 0, 0, 0, 0, 0, 'The Family Zealot - On Aggro'),
(164310, 0, 1, '我要把你的尸体和他们一起扔进深坑！', 14, 0, 25, 0, 0, 0, 0, 0, 'The Family Zealot - On Aggro'),
(164310, 0, 2, '你来晚了！', 14, 0, 25, 0, 0, 0, 0, 0, 'The Family Zealot - On Aggro'),
(164310, 0, 3, '你阻止不了血亲实现它的宏图！', 14, 0, 25, 0, 0, 0, 0, 0, 'The Family Zealot - On Aggro'),
(164312, 0, 0, '愿暗影吞噬你！', 14, 0, 25, 0, 0, 0, 0, 0, 'The Family Cultist - On Aggro'),
(164312, 0, 1, '我要把你的尸体和他们一起扔进深坑！', 14, 0, 25, 0, 0, 0, 0, 0, 'The Family Cultist - On Aggro'),
(164312, 0, 2, '你来晚了！', 14, 0, 25, 0, 0, 0, 0, 0, 'The Family Cultist - On Aggro'),
(164312, 0, 3, '你阻止不了血亲实现它的宏图！', 14, 0, 25, 0, 0, 0, 0, 0, 'The Family Cultist - On Aggro'),
(164314, 0, 0, '无关紧要。我快完成了。它已经在我体内了！它在扭动。它在嬉戏。它在踢踹。哦……', 14, 0, 100, 0, 0, 0, 0, 0, 'Patriarch Tharion - On Aggro'),
(164314, 1, 0, '那湿漉漉的声音……那是你流下的血。', 14, 0, 100, 0, 0, 0, 0, 0, 'Patriarch Tharion - At 66% HP'),
(164314, 2, 0, '你会死在这下面，圣光永远找不到你。', 14, 0, 100, 0, 0, 0, 0, 0, 'Patriarch Tharion - At 33% HP'),
(164314, 3, 0, '家族……把一切都押上了……就赌这一步……', 14, 0, 100, 0, 0, 0, 0, 0, 'Patriarch Tharion - On Death'),
(164317, 0, 0, '为了祖灵！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kharadol Ealdir - aggro'),
(164317, 0, 1, '城里的渣滓。', 14, 0, 100, 0, 0, 0, 0, 0, 'Kharadol Ealdir - aggro'),
(164317, 0, 2, '祖灵正对我们的伟业微笑！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kharadol Ealdir - aggro'),
(164317, 0, 3, '艾尔迪尔必胜！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kharadol Ealdir - aggro'),
(164317, 0, 4, '你们都是闯入我们土地的入侵者。', 14, 0, 100, 0, 0, 0, 0, 0, 'Kharadol Ealdir - aggro'),
(164317, 0, 5, '血流成河。', 14, 0, 100, 0, 0, 0, 0, 0, 'Kharadol Ealdir - aggro'),
(164317, 0, 6, '女巫会把你的孩子带走！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kharadol Ealdir - aggro'),
(164317, 0, 7, '王国必亡！', 14, 0, 100, 0, 0, 0, 0, 0, 'Kharadol Ealdir - aggro'),
(164327, 0, 0, '很抱歉我帮不上更多的忙。我看到的不多……我只是一直在跑。艾尔迪尔带走了其他所有人。你……你觉得他们还活着吗？', 12, 0, 100, 0, 0, 0, 0, 0, 'Mayv - 175110 accepted'),
(164339, 0, 0, '赛达恩酋长以残忍和急躁闻名；他很少在一个地方久留。你得把布赖卡格高地翻个遍才能找到他。', 12, 0, 100, 0, 0, 0, 0, 0, 'Laurelin - On Chieftain Saidarn accepted'),
(164340, 0, 0, '巴加·达尔玛是位强大的女巫。即便你能出其不意地接近她，也千万不要低估她。', 12, 0, 100, 0, 0, 0, 0, 0, 'Telperion - On The Witch of My Nightmares accepted'),
(164340, 1, 0, '等你靠近巴列斯卡达，只需摩擦护符触发法术，便可化作猫形。不必多说，但……艾尔迪尔人绝非蠢货，他们施的魔法可不是糊弄人的把戏。谨慎行事。', 12, 0, 100, 0, 0, 0, 0, 0, 'Telperion - On The Ealdir of Baile Escada accepted'),
(164341, 0, 0, '血流成河。', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 1, '王国必亡！', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 2, '你们全是闯入我们土地的入侵者。', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 3, '为了祖灵！', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 4, '女巫会把你们的孩子带走！', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 5, '让斯卡德尔德自由！', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 6, '城里的渣滓。', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 7, '斯卡德尔德必将自由！', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 8, '艾尔迪尔必胜！', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164341, 0, 9, '祖灵眷顾我们的事业！', 14, 0, 100, 0, 0, 0, 0, 0, 'Braicag Ealdir - Aggro'),
(164342, 0, 0, '哈！我当是谁在窃窃私语，原来是老鼠！来吧！与我正面一战！', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Saidarn - Aggro'),
(164342, 1, 0, '祖灵当真慷慨！终于来了个配得上斯凯达恩的对手！', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Saidarn - At half health'),
(164342, 2, 0, '啊……这份力量……足以……担当酋长……', 14, 0, 100, 0, 0, 0, 0, 0, 'Chieftain Saidarn - Death'),
(164344, 0, 0, '瞧瞧这是什么？又一批不听话的小崽子，等着下锅？我的肚子才刚叫起来呢！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bagga Darma - Aggro'),
(164344, 1, 0, '小可爱们，你们可活不到自己看起来的那把年纪！哈！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bagga Darma - Combat'),
(164344, 1, 1, '上回那个敲我门的崽子，骨头被我熬成了一锅好汤。想想看，像你这样有滋味的小点心，该有多香！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bagga Darma - Combat'),
(164344, 1, 2, '我要把你变成苍蝇去喂我的蟾蜍。它们最爱还会抽搐的零嘴！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bagga Darma - Combat'),
(164344, 1, 3, '你就这么急着去见那位在斯卡德尔德地底百口流涎、百蹄踏地的存在？它准是饿坏了！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bagga Darma - Combat'),
(164344, 2, 0, '哈！我笑着进坟墓……因为我知道，等着你们这些家伙的会是怎样的美餐！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bagga Darma - Death'),
(164345, 0, 0, '先是我的儿子，守卫攻打瓦尔滕村的时候。然后是我的孙子，只为他想替父亲报仇。别跟我谈牺牲，也别谈什么大义，明德拉。女巫们只肯用我们的血来买斯卡德尔德的自由。', 12, 0, 100, 0, 0, 0, 0, 0, 'Baig Dyras'),
(164346, 0, 0, '换作我，说话会小心些，拜格。女巫集会到处都有耳朵。再说，人人都说多亏了大母神，战争很快就要结束。到那时，我们就能迎来和平了。', 12, 0, 100, 0, 0, 0, 0, 0, 'Mindra Roble'),
(164347, 0, 0, '森林之灵。巨鹿、恐狼、蜘蛛祖母。回应我的召唤。', 12, 0, 100, 0, 0, 0, 0, 0, 'Goldarn'),
(164347, 1, 0, '大地为何在尖啸哀鸣？元素为何躁动不安？源头就是那场仪式吗？摩根娜那可怖的计划？', 12, 0, 100, 0, 0, 0, 0, 0, 'Goldarn'),
(164355, 0, 0, '瞧瞧这是谁？哦，这不是我见过最漂亮的猫儿吗。', 12, 0, 100, 0, 0, 0, 0, 0, 'Deirdre'),
(164355, 1, 0, '我们艾尔迪尔人已经打了几个世纪的仗。我的祖母，她的祖母，再往前的祖母……我们都同样鄙视暴风城，鄙视格雷斯基。鄙视你们的宗教、你们的习俗。还有你们的狂热。', 12, 0, 100, 0, 0, 0, 0, 0, 'Deirdre'),
(164355, 2, 0, '我不敢断言，但姐妹们之间的私语表明，摩根娜打算放出盘根之影——我们万神殿中最黑暗的灵。', 12, 0, 100, 0, 0, 0, 0, 0, 'Deirdre'),
(164355, 3, 0, '若果真如此，若她真的得逞……我们都死定了。斯卡德尔德、暴风城，以及方圆数里格之内的每一片邻土。', 12, 0, 100, 0, 0, 0, 0, 0, 'Deirdre'),
(164355, 4, 0, '摩根娜的党羽把碎岩的俘虏带去了西边的影骨深渊。可那些洞窟有强大的结界守护。我需要摩根娜的魔典，才能找到穿过她防御的办法，阻止这场仪式。', 12, 0, 100, 0, 0, 0, 0, 0, 'Deirdre'),
(164355, 5, 0, '在峭壁最高处的巨鹿祭坛献上护符。', 12, 0, 100, 0, 0, 0, 0, 0, 'Deirdre'),
(164355, 6, 0, '用塞伦娅·冷沼的命换摩根娜的命。格雷斯基的首领与艾尔迪尔的首领。等两人都冷在土里……便是和平。至少算是和平吧。能维持一阵子。', 12, 0, 100, 0, 0, 0, 0, 0, 'Deirdre'),
(164376, 0, 0, '若你在穿行蜿蜒之路时，发现任何能揭开袭击幕后主使的线索，请将结果呈交给参议员萨加斯·安威玛尔。', 12, 0, 100, 0, 0, 0, 0, 0, 'Mountaineer Captain Kildar - Bitter Legacy of the War accepted'),
(164377, 0, 0, '<一名矮人的尸体，衣着与勋章皆是铁炉堡外交官的规格。奇怪的是：所有尸体都属于外交使团成员。难道没有一个伏击者死去？那么，车队其余的生还者又是如何逃脱的？>', 42, 0, 100, 0, 0, 0, 0, 0, 'Ironforge Diplomatic - corpse inspected'),
(164393, 0, 0, '警报，又是警报！矿道地铁的水下玻璃已处于危急状态！', 12, 0, 100, 0, 0, 0, 0, 0, 'Mekgineer Naudin Screwdriver - player arrives'),
(164399, 0, 0, '生还者？啊，不是。那你就是从外面来的。你是来送死的。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sardragar - aggro'),
(164399, 1, 0, '让暗影带走你！', 14, 0, 100, 0, 0, 0, 0, 0, 'Sardragar - combat'),
(164399, 1, 1, '你的灵魂去不了什么好地方。它将被暗影与烈焰吞噬', 14, 0, 100, 0, 0, 0, 0, 0, 'Sardragar - combat'),
(164399, 2, 0, '伤害……已经造成了……', 12, 0, 100, 0, 0, 0, 0, 0, 'Sardragar - death'),
(164431, 0, 0, '又少了一桩烦心事。', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164431, 0, 1, '为了霜鬃！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164431, 0, 2, '老子才不怕你！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164431, 0, 3, '你的死让我们离荣耀岁月更近一步！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164431, 0, 4, '老子连尸首都不给你亲人留，哭去吧……', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164431, 0, 5, '我们要把你们全杀光。就从你开始！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164431, 0, 6, '你凭什么以为打得过我？', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164431, 0, 7, '你祖先偷走的东西，你要拿命来还！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164431, 0, 8, '这片土地是我们的！', 14, 0, 100, 0, 0, 0, 0, 0, 'Bonesurper Troll - aggro yell'),
(164432, 0, 0, '死在墓里，倒真是合适……', 14, 0, 100, 0, 0, 0, 0, 0, 'Necrotic Witch Altamira - yell'),
(164432, 0, 1, '沉睡之父正等着你呢！', 14, 0, 100, 0, 0, 0, 0, 0, 'Necrotic Witch Altamira - yell'),
(164432, 0, 2, '啊，暗夜之友送来的礼物。我的后宫又添灵魂了！', 14, 0, 100, 0, 0, 0, 0, 0, 'Necrotic Witch Altamira - yell'),
(164433, 0, 0, '站住，巨魔渣滓！放下武器，否则我们就炸掉你的——！哦。', 12, 0, 100, 0, 0, 0, 0, 0, 'Guard Captain Erdruin'),
(164433, 1, 0, '杀了他们。让他们尝尝他们对我族人的那份慈悲，把他们的残骸撒遍山野！', 12, 0, 100, 0, 0, 0, 0, 0, 'Guard Captain Erdruin'),
(164438, 0, 0, '公主有了强大的盟友……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 1, '为了梅克西特拉！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 2, '你的孩子会变成孤儿……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 3, '为了霜鬃！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 4, '我打赌你味道不错……让我咬一口！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 5, '我得到了洛阿的祝福！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 6, '老子连尸首都不给你亲人留，哭去吧……', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 7, '为了古老帝国！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 8, '德鲁克塔尔永存！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 9, '死！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 10, '我们要把你们全杀光。就从你开始！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 11, '你的死让我们离荣耀岁月更近一步！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 12, '你凭什么以为打得过我？', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 13, '绝不留情！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 14, '我杀过几十个你这样的家伙……你怎么就不肯认输？', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 15, '梅克西特拉必胜！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 16, '我要全吃光！连骨头都不剩！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 17, '老子才不怕你！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 18, '这片土地是我们的！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 0, 19, '你祖先偷走的东西，你要拿命来还！', 14, 0, 5, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164438, 1, 0, '又少了一桩烦心事。', 14, 0, 100, 0, 0, 0, 0, 0, 'Frostmane Raider'),
(164441, 0, 0, '还以为把你们杀光了。幸好没有……我正开始觉得无聊！', 14, 0, 100, 0, 0, 0, 0, 0, 'Frostmane Taskmaster Migbala - aggro'),
(164443, 0, 0, '你来这里是个错误。', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164443, 0, 1, '不胜利，毋宁死！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164443, 0, 2, '你以为自己有那本事？证明给我看！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164443, 0, 3, '去死！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164443, 0, 4, '为了部落！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164444, 0, 0, '你来这里是个错误。', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164444, 0, 1, '不胜利，毋宁死！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164444, 0, 2, '你以为自己有那本事？证明给我看！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164444, 0, 3, '去死！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164444, 0, 4, '为了部落！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164445, 0, 0, '你来这里是个错误。', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164445, 0, 1, '不胜利，毋宁死！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164445, 0, 2, '你以为自己有那本事？证明给我看！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164445, 0, 3, '去死！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164445, 0, 4, '为了部落！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164446, 0, 0, '你来这里是个错误。', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164446, 0, 1, '不胜利，毋宁死！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164446, 0, 2, '你以为自己有那本事？证明给我看！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164446, 0, 3, '去死！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164446, 0, 4, '为了部落！', 14, 0, 100, 0, 0, 0, 0, 0, 'Horde Collaborator - aggro'),
(164448, 0, 0, '退后！退后，你们这些虫子！否则我便不再留情，将你们碾在脚下。', 14, 0, 100, 0, 0, 0, 0, 0, 'Elder Thrymus the Astray - aggro'),
(164454, 0, 0, '我们在此聚集，向丹卡扎德的勇士霍尔多尔·石拳的灵魂告别。', 12, 0, 100, 0, 0, 0, 0, 0, 'Bishop Beorn - Farewell Ceremony sermon'),
(164454, 1, 0, '因此，正如圣光将他的灵魂托举至苍穹之巅，我们亦献上祈祷，与他同行。', 12, 0, 100, 0, 0, 0, 0, 0, 'Bishop Beorn - Farewell Ceremony sermon'),
(164454, 2, 0, '越过痛苦与悲伤。去往那处唯有极乐与安宁之地。', 12, 0, 100, 0, 0, 0, 0, 0, 'Bishop Beorn - Farewell Ceremony sermon'),
(164454, 3, 0, '蒙圣光恩典，他已与神圣合为一体。', 12, 0, 100, 0, 0, 0, 0, 0, 'Bishop Beorn - Farewell Ceremony sermon'),
(164469, 0, 0, '终于来了个会打的！', 14, 0, 100, 0, 0, 0, 0, 0, 'Shadowburn Outrider - aggro yell'),
(164518, 0, 0, '一只破碎的木桶，在露天里搁了很久。', 41, 0, 100, 0, 0, 0, 0, 0, 'Smashed Barrel clue'),
(164518, 1, 0, '生鱼的残骸，半埋在泥里。臭气熏天。', 41, 0, 100, 0, 0, 0, 0, 0, 'Raw fish clue'),
(164518, 2, 0, '鱼被串在鱼人的长矛上。这景象既粗俗又令人不适。', 41, 0, 100, 0, 0, 0, 0, 0, 'Skewered fish clue'),
(164518, 3, 0, '一只靴子，裹满泥浆，脚踝处已经弯折。从尺寸看，它属于一个成年人。', 41, 0, 100, 0, 0, 0, 0, 0, 'Boot clue'),
(164518, 4, 0, '一件鱼人制作的粗劣工具。看不出使用过的痕迹。', 41, 0, 100, 0, 0, 0, 0, 0, 'Murloc Tool clue'),
(164520, 0, 0, '一把磨损的镐子，镐头崩了口，木柄沾满污垢。这样的东西你见过上百把。', 41, 0, 100, 0, 0, 0, 0, 0, 'Pickaxe clue'),
(164520, 1, 0, '一颗发黄的狗头人颅骨。身体的其余部分毫无踪影。', 41, 0, 100, 0, 0, 0, 0, 0, 'Kobold Skull clue'),
(164520, 2, 0, '狗头人搭的临时梯子。确实简陋，也确实巧妙。', 41, 0, 100, 0, 0, 0, 0, 0, 'Ladder clue'),
(164520, 3, 0, '一辆摇摇欲坠的矿车，用碎裂的木片和锈钉补过。没什么特别的。', 41, 0, 100, 0, 0, 0, 0, 0, 'Kobold Cart clue'),
(164520, 4, 0, '铲刃磨损得厉害，看着比暴风城王国还要古老。', 41, 0, 100, 0, 0, 0, 0, 0, 'Shovel clue'),
(164588, 0, 0, '上前来，年轻人。你脚上的尘土令我们欣慰。你远道而来，为的是一桩高尚的事业。', 12, 0, 100, 0, 0, 0, 0, 0, 'Maiden - greeting on arrival'),
(164589, 0, 0, '上前来，年轻人。你脚上的尘土令我们欣慰。你远道而来，为的是一桩高尚的事业。', 12, 0, 100, 0, 0, 0, 0, 0, 'Mother - greeting on arrival'),
(164590, 0, 0, '上前来，年轻人。你脚上的尘土令我们欣慰。你远道而来，为的是一桩高尚的事业。', 12, 0, 100, 0, 0, 0, 0, 0, 'Crone - greeting on arrival'),
(164593, 0, 0, '得到祝福后，去格雷斯基找卡萨尔。就说是我让你去的，他会帮你找到三姐妹。', 12, 0, 100, 0, 0, 0, 0, 0, 'Aisling - On Triple Blessing accepted'),
(164593, 1, 0, '阿兰娜……我一直知道，卡登那家伙会害了你。', 12, 0, 100, 0, 0, 0, 0, 0, 'Aisling - On hearing of Alanna'),
(164594, 0, 0, '你说埃卡蒂娅？竟敢求见，胆子不小。也罢，我倒觉得有趣！别动，就一会儿。', 12, 0, 100, 0, 0, 0, 0, 0, 'Ann'),
(164597, 0, 0, '进了地窖后，找地板上的暗门。然后沿着穿过峡谷的小路，前往初咒洞穴。', 12, 0, 100, 0, 0, 0, 0, 0, 'Cathal'),
(164806, 0, 0, '诺莫瑞根发生的事是侏儒自己造成的，但付出代价的不止他们。', 12, 0, 100, 0, 0, 0, 0, 0, 'Anzuldin, Leopard Loa'),
(164806, 1, 0, '那片绿色的疫病——辐射——渗过大地，最终流到了马特拉坎神庙。', 12, 0, 100, 0, 0, 0, 0, 0, 'Anzuldin, Leopard Loa'),
(164806, 2, 0, '河流洛阿因此陷入疯狂。', 12, 0, 100, 0, 0, 0, 0, 0, 'Anzuldin, Leopard Loa'),
(164806, 3, 0, '他的饥饿化作一团丑陋臃肿之物。他的身心像蛞蝓般膨胀，又像溃烂的脓包般爆开。', 12, 0, 100, 0, 0, 0, 0, 0, 'Anzuldin, Leopard Loa'),
(164806, 4, 0, '然而马特拉坎的信徒把这悲剧视作信仰的试炼，将辐射奉为神圣之物。', 12, 0, 100, 0, 0, 0, 0, 0, 'Anzuldin, Leopard Loa'),
(164806, 5, 0, '他们自称病光之子。许久以来，他们一直与其余霜鬃部族打着一场内战，只为满足他们洛阿那反复无常、永无止境的食欲。', 12, 0, 100, 0, 0, 0, 0, 0, 'Anzuldin, Leopard Loa'),
(164806, 6, 0, '而每过一天，他们的人数都在增加。', 12, 0, 100, 0, 0, 0, 0, 0, 'Anzuldin, Leopard Loa'),
(164806, 7, 0, '你来了。再近些……靠近点。我只在饿极的时候才咬人。', 12, 0, 100, 0, 0, 0, 0, 0, 'Anzuldin, Leopard Loa'),
(164981, 0, 0, '照那帮人动手的磨蹭劲，我先饿死了……', 12, 0, 100, 0, 0, 0, 0, 0, 'Baldur'),
(164982, 0, 0, '但愿快了……', 12, 0, 100, 0, 0, 0, 0, 0, 'Jelena Goret'),
(164983, 0, 0, '该死的贵族。他们的不作为要我们来承担后果……他们从不挺身而出，可你准能感觉到他们的手伸进你的口袋。', 12, 0, 100, 0, 0, 0, 0, 0, 'Gareth Lindgren'),
(164984, 0, 0, '又是空话，一如既往……这回是不是空话，我们等着瞧。', 12, 0, 100, 0, 0, 0, 0, 0, 'Sereniel'),
(164985, 0, 0, '即便在迷茫之时，圣光也指引着我们。我深信于此。', 12, 0, 100, 0, 0, 0, 0, 0, 'Brother Caesar');
