INSERT INTO `gossip_menu_option` (`MenuID`, `OptionID`, `OptionIcon`, `OptionText`, `OptionBroadcastTextID`, `OptionType`, `OptionNpcFlag`, `ActionMenuID`, `ActionPoiID`, `BoxCoded`, `BoxMoney`, `BoxText`, `BoxBroadcastTextID`, `VerifiedBuild`) VALUES
(100705, 0, 0, '（任务）我是来协助你训练的。准备战斗！', 0, 1, 1, 0, 0, 0, 0, '', 0, NULL),
(100708, 0, 0, '丹卡扎德的军队由你统率吗？', 0, 1, 1, 1200437, 0, 0, 0, '', 0, 0),
(100708, 1, 0, '丹卡扎德是什么意思？', 0, 1, 1, 1200439, 0, 0, 0, '', 0, 0),
(100710, 0, 0, '|cFF0000FF（任务）|r依照圣光教会的说法，霍尔多尔的灵魂将归向何处？', 0, 1, 1, 100712, 0, 0, 0, '', 0, 0),
(100710, 1, 0, '|cFF0000FF（任务）|r圣光的信条是什么？', 0, 1, 1, 100713, 0, 0, 0, '', 0, 0),
(100710, 2, 0, '|cFF0000FF（任务）|r可以开始了', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100711, 0, 0, '|cFF0000FF（任务）|r依照万神殿信条的说法，霍尔多尔的灵魂将归向何处？', 0, 1, 1, 100714, 0, 0, 0, '', 0, 0),
(100711, 1, 0, '|cFF0000FF（任务）|r万神殿信条的内容是什么？', 0, 1, 1, 100715, 0, 0, 0, '', 0, 0),
(100711, 2, 0, '|cFF0000FF（任务）|r可以开始了', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100716, 0, 0, '|cFF0000FF（任务）|r贝奥恩派我来的。石拳家族已决定皈依圣光', 0, 1, 1, 100718, 0, 0, 0, '', 0, 0),
(100717, 0, 0, '|cFF0000FF（任务）|r卡泽米尔派我来的。石拳家族已决定皈依万神殿信条', 0, 1, 1, 100719, 0, 0, 0, '', 0, 0),
(100722, 0, 0, '|cFF0000FF（任务）|r我在寻找三姐妹，需要三位女巫的祝福才能抵达那里。', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100725, 0, 0, '我想回去。', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100727, 0, 0, '|cFF0000FF（任务）|r阿兰娜派我来的。<你讲述了墓穴中发生的事：阿兰娜以亡灵之身复活，以及她的求助。>', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100728, 0, 0, '<你把豺狼人的实情告诉了他，却避而不谈女巫的插手。>', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100728, 1, 0, '<你把女巫贝尔德雷德与豺狼人所受的诅咒，一五一十地全说了出来。>', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100729, 0, 0, '你是谁？', 0, 1, 1, 100730, 0, 0, 0, '', 0, 0),
(100729, 1, 0, '你支持艾尔迪尔的事业吗？', 0, 1, 1, 100731, 0, 0, 0, '', 0, 0),
(100730, 0, 0, '你怎么可能活了这么久？你难道不是人类吗？', 0, 1, 1, 100732, 0, 0, 0, '', 0, 0),
(100736, 0, 0, '贵族议会正在采取行动，解决此事。', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(100737, 0, 0, '贵族议会正在采取行动，解决此事。', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
