(9997001, 0, 0, '<你低声念了一段简短的祷词。>', 0, 1, 1, 0, 0, 0, 0, '', 0, 0),
(9997002, 0, 0, '你治理这片行省多久了？', 0, 1, 1, 9997003, 0, 0, 0, '', 0, 0),
(9997002, 1, 0, '既然斯卡德尔德的情况如此危急，为何不向贵族议会求援？', 0, 1, 1, 9997004, 0, 0, 0, '', 0, 0),
(9997005, 0, 0, '关于这座城的起源，你能说些什么？', 0, 1, 1, 9997006, 0, 0, 0, '', 0, 0),
